import{_ as a,o as t,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetCircMode 设置圆弧姿态模式","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetCircMode.md","filePath":"3. 指令/5. 设置指令/SetCircMode.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/SetCircMode.md"};function r(o,s,d,l,h,p){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="setcircmode-设置圆弧姿态模式" tabindex="-1">SetCircMode 设置圆弧姿态模式 <a class="header-anchor" href="#setcircmode-设置圆弧姿态模式" aria-label="Permalink to &quot;SetCircMode 设置圆弧姿态模式&quot;">​</a></h1><p>该指令用于<strong>设置机器人在执行圆弧运动（<code>MovC</code>）时的姿态插补模式</strong>。它决定了机器人在经过圆弧中间点（辅助点）时，末端工具的姿态是如何过渡的。这对于需要高精度姿态控制的工艺（如焊接或涂胶）至关重要。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetCircMode(CircMode) SetCircMode(圆弧模式)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>CircMode：圆弧模式</td><td>enum（枚举型）</td><td>定义圆弧运动中的姿态插补方式。<br>* <strong>Standard（标准模式）</strong>：<strong>默认设置</strong>。系统主要关注起点和终点的姿态，中间点的姿态仅作为轨迹参考。在某些大跨度的圆弧中，这可能导致工具在圆弧中段的指向偏离预期。<br>* <strong>MidPosePass（过中间点模式）</strong>：<strong>开启姿态插补优化</strong>。系统会强制要求机器人精确经过中间辅助点所定义的姿态。<strong>核心优势</strong>：在以往的逻辑中，如果要保持复杂的焊接角度，必须将一个圆拆分成 3-4 段小圆弧分段编程；开启此模式后，仅需一个 <code>MovC</code> 即可实现连续、平滑的姿态过渡。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>在圆弧运动中，TCP 始终沿着圆弧路径走。但在 <code>Standard</code> 模式下，工具姿态可能会在起点和终点之间以非理想的方式&quot;扭转&quot;。<code>MidPosePass</code> 将中间点的姿态也纳入插补计算，使整个圆弧过程中的姿态变化更加平滑且符合物理路径。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 场景：焊接一个半圆，要求焊枪始终指向圆心</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetCircMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MidPosePass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// P1 为圆弧中间点，P2 为圆弧终点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人执行圆弧运动，且焊枪在经过 <strong>P1</strong> 时，其角度会严格匹配 P1 示教时的姿态，确保整个焊接过程的入热角度一致。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>圆管焊接</strong>：在绕着圆管焊接时，焊枪角度需要随着弧度实时变化。开启 <code>MidPosePass</code> 可以用最少的点位实现完美的焊缝。</li><li><strong>复杂涂胶</strong>：在曲面或圆形凹槽边缘涂胶，要求胶枪始终垂直于工作面。</li><li><strong>抛光打磨</strong>：在圆形工件表面作业时，保持打磨盘与表面的恒定接触角度。</li></ul><hr><h3 id="💡-总结" tabindex="-1"><strong>💡 总结</strong> <a class="header-anchor" href="#💡-总结" aria-label="Permalink to &quot;**💡 总结**&quot;">​</a></h3><ul><li><strong>想要编程简单且姿态过渡自然？</strong> 使用 <code>MidPosePass</code>。</li><li><strong>普通的圆弧搬运（不关心末端朝向）？</strong> 使用 <code>Standard</code> 即可。</li></ul>`,21)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
